#!/usr/bin/env bash
# Build a `mastro` wrapper script for convenience.
#
# The wrapper runs the compiled CLI from this checkout while keeping your
# current directory: path arguments like `new my_app` land where you are, and
# commands that act on an app (`gen resource`, `link`, `migrate`) run inside
# it. Only `erl` is needed at run time, not `gleam`.
#
# Usage:
#   ./bin/build-cli.sh
#   ./mastro new my_app --db sqlite
#
set -euo pipefail

root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"

gleam build

cat > "$root/mastro" <<SCRIPT
#!/bin/sh
# Mastro CLI — generated by bin/build-cli.sh, bound to $root
exec erl -noshell -pa "$root"/build/dev/erlang/*/ebin \\
  -eval 'mastro@cli:main(), init:stop().' -extra "\$@"
SCRIPT

chmod +x "$root/mastro"
echo "Created $root/mastro"
echo "Run: $root/mastro new my_app --db sqlite"
